mapper.select:



        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            WHERE d.distribute_id = rc.distribute_id
            AND d.breed_seed_produce_batch_id = #{query.breedSeedProduceBatchId}
        )


        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            WHERE d.distribute_id = rc.distribute_id
            AND d.crop_type = #{query.cropType}
        )


        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            WHERE d.distribute_id = rc.distribute_id
            AND d.variety_name LIKE CONCAT('%', #{query.varietyName}, '%')
        )


        AND DATE(rc.create_time) >= #{query.startTime}


        AND DATE(rc.create_time) <= #{query.endTime}


        AND rc.receive_status = #{query.receiveStatus}


ORDER BY rc.create_time DESC
